```apex
public with sharing class LogPurgeJob implements Schedulable {

    public static final String JOB_NAME = 'Log purge (nightly)';
    public static final String CRON_NIGHTLY = '0 0 2 * * ?';

    public LogPurgeJob() {
    }

    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, CRON_NIGHTLY, new LogPurgeJob());
    }

    public void execute(SchedulableContext sc) {
        Datetime now = System.now();
        Database.executeBatch(new PurgeBatch(now.addDays(-30), now.addDays(-180)), 2000);
    }

    public class PurgeBatch implements Database.Batchable<SObject> {
        private final Datetime generalCutoff;
        private final Datetime errorCutoff;

        public PurgeBatch(Datetime generalCutoff, Datetime errorCutoff) {
            this.generalCutoff = generalCutoff;
            this.errorCutoff = errorCutoff;
        }

        public Database.QueryLocator start(Database.BatchableContext bc) {
            return Database.getQueryLocator([
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (CreatedDate < :generalCutoff
                       AND (Level__c = null OR Level__c != 'ERROR'))
                   OR (CreatedDate < :errorCutoff AND Level__c = 'ERROR')
            ]);
        }

        public void execute(Database.BatchableContext bc, List<SObject> scope) {
            Database.delete(scope, false);
            Database.emptyRecycleBin(scope);
        }

        public void finish(Database.BatchableContext bc) {
        }
    }
}
