@IsTest
private class OpportunitiesServiceTest {

    private static void assertInvalid(Decimal pct) {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunities domainMock = (IOpportunities) mocks.mock(IOpportunities.class);
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_SObjectUnitOfWork.class);

        mocks.startStubbing();
        mocks.when(domainMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.stopStubbing();

        Application.Domain.setMock(domainMock);
        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Boolean thrown = false;
        Test.startTest();
        try {
            OpportunitiesService.applyDiscounts(
                new Set<Id>{ fflib_IDGenerator.generate(Opportunity.SObjectType) }, pct);
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            thrown = true;
        }
        Test.stopTest();

        System.assert(thrown, 'Expected exception for percentage ' + pct);
        ((IOpportunities) mocks.verify(domainMock, mocks.never()))
            .applyDiscount((Decimal) fflib_Match.anyObject(), (fflib_ISObjectUnitOfWork) fflib_Match.anyObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).commitWork();
        ((IOpportunitiesSelector) mocks.verify(selectorMock, mocks.never()))
            .selectById((Set<Id>) fflib_Match.anyObject());
    }

    @IsTest
    static void zeroPercentageThrows() {
        assertInvalid(0);
    }

    @IsTest
    static void negativePercentageThrows() {
        assertInvalid(-5);
    }

    @IsTest
    static void nullPercentageThrows() {
        assertInvalid(null);
    }

    @IsTest
    static void aboveMaximumThrows() {
        assertInvalid(50.01);
    }

    @IsTest
    static void nullIdsDoNothing() {
        assertNoWork(null);
    }

    @IsTest
    static void emptyIdsDoNothing() {
        assertNoWork(new Set<Id>());
    }

    private static void assertNoWork(Set<Id> ids) {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunities domainMock = (IOpportunities) mocks.mock(IOpportunities.class);
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_SObjectUnitOfWork.class);

        mocks.startStubbing();
        mocks.when(domainMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.stopStubbing();

        Application.Domain.setMock(domainMock);
        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        OpportunitiesService.applyDiscounts(ids, 10);
        Test.stopTest();

        ((IOpportunities) mocks.verify(domainMock, mocks.never()))
            .applyDiscount((Decimal) fflib_Match.anyObject(), (fflib_ISObjectUnitOfWork) fflib_Match.anyObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.never())).commitWork();
