    @IsTest
    static void appliesDiscountThenCommitsAtMaximum() {
        runHappyPath(50);
    }

    @IsTest
    static void appliesDiscountThenCommitsSmallValue() {
        runHappyPath(0.5);
    }

    private static void runHappyPath(Decimal pct) {
        Id oppId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Set<Id> ids = new Set<Id>{ oppId };
        List<Opportunity> records = new List<Opportunity>{
            new Opportunity(Id = oppId, Name = 'Test', Amount = 100)
        };

        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IOpportunities domainMock = (IOpportunities) mocks.mock(IOpportunities.class);
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uowMock = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_SObjectUnitOfWork.class);

        mocks.startStubbing();
        mocks.when(domainMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(selectorMock.selectById(ids)).thenReturn(records);
        mocks.stopStubbing();

        Application.Domain.setMock(domainMock);
        Application.Selector.setMock(selectorMock);
        Application.UnitOfWork.setMock(uowMock);

        Test.startTest();
        OpportunitiesService.applyDiscounts(ids, pct);
        Test.stopTest();

        fflib_InOrder inOrder = new fflib_InOrder(mocks, new List<Object>{ domainMock, uowMock });
        ((IOpportunities) inOrder.verify(domainMock, mocks.times(1)))
            .applyDiscount(pct, uowMock);
        ((fflib_ISObjectUnitOfWork) inOrder.verify(uowMock, mocks.times(1))).commitWork();

        ((IOpportunities) mocks.verify(domainMock, mocks.times(1)))
            .applyDiscount((Decimal) fflib_Match.anyObject(), (fflib_ISObjectUnitOfWork) fflib_Match.anyObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uowMock, mocks.times(1))).commitWork();
        ((IOpportunitiesSelector) mocks.verify(selectorMock, mocks.times(1))).selectById(ids);
    }
}
