public with sharing class FollowUpTaskService {

    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOppIds = new Set<Id>();
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOppIds;
        }

        Set<Id> requestedIds = new Set<Id>();
        for (Id oppId : opportunityIds) {
            if (oppId != null) {
                requestedIds.add(oppId);
            }
        }

        Map<Id, Opportunity> oppsById = new Map<Id, Opportunity>(
            [SELECT Id, Name, OwnerId
             FROM Opportunity
             WHERE Id IN :requestedIds
             WITH USER_MODE]
        );

        List<Task> tasks = new List<Task>();
        List<Id> taskOppIds = new List<Id>(); // parallel to tasks
        Date dueDate = Date.today().addDays(7);

        for (Id oppId : requestedIds) {
            Opportunity opp = oppsById.get(oppId);
            if (opp == null) {
                // Not found or not visible: no task can be created
                failedOppIds.add(oppId);
                continue;
            }
            tasks.add(new Task(
                WhatId = opp.Id,
                OwnerId = opp.OwnerId,
                Subject = 'Follow up: ' + opp.Name,
                ActivityDate = dueDate,
                Status = 'Not Started',
                Priority = 'Normal'
            ));
            taskOppIds.add(opp.Id);
        }

        if (!tasks.isEmpty()) {
            List<Database.SaveResult> results = Database.insert(tasks, false);
            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    failedOppIds.add(taskOppIds[i]);
                }
            }
        }

        return failedOppIds;
    }
}
