public with sharing class AccountCountrySync {

    public static void syncContactCountries(List<Account> newAccounts, Map<Id, Account> oldMap) {
        Map<Id, String> oldCountryByAccount = new Map<Id, String>();
        Map<Id, String> newCountryByAccount = new Map<Id, String>();

        for (Account acc : newAccounts) {
            Account oldAcc = oldMap == null ? null : oldMap.get(acc.Id);
            if (oldAcc == null) {
                continue;
            }
            if (acc.BillingCountry != oldAcc.BillingCountry) {
                oldCountryByAccount.put(acc.Id, oldAcc.BillingCountry);
                newCountryByAccount.put(acc.Id, acc.BillingCountry);
            }
        }

        if (newCountryByAccount.isEmpty()) {
            return;
        }

        // Single selective query, restricted to the accounts that changed.
        List<Contact> toUpdate = new List<Contact>();
        for (Contact c : [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :newCountryByAccount.keySet()
        ]) {
            String oldCountry = oldCountryByAccount.get(c.AccountId);
            String newCountry = newCountryByAccount.get(c.AccountId);

            Boolean blankMailing = String.isBlank(c.MailingCountry);
            Boolean matchesOld = !blankMailing
                && !String.isBlank(oldCountry)
                && c.MailingCountry.equalsIgnoreCase(oldCountry);

            if ((blankMailing || matchesOld) && c.MailingCountry != newCountry) {
                c.MailingCountry = newCountry;
                toUpdate.add(c);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
