        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
        // Keep active option valid if options changed
        if (!this._options.some((o) => o.value === this._activeValue)) {
            this._activeValue = undefined;
        }
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        // Parent change moves the active option to the selection
        this._activeValue = val;
    }

    get effectiveActiveValue() {
        const opts = this._options;
        if (opts.some((o) => o.value === this._activeValue)) {
            return this._activeValue;
        }
        if (opts.some((o) => o.value === this._value)) {
            return this._value;
        }
        return opts.length ? opts[0].value : undefined;
    }

    get items() {
        const active = this.effectiveActiveValue;
        return this._options.map((o, i) => ({
            key: 'opt-' + i,
            id: 'opt-' + i,
            value: o.value,
            label: o.label,
            selected: this._value !== undefined && this._value !== null && this._value !== '' && o.value === this._value
                ? 'true'
                : 'false',
            isActive: o.value === active
        }));
    }

    get activeDescendant() {
        const idx = this._options.findIndex((o) => o.value === this.effectiveActiveValue);
        return idx >= 0 ? 'opt-' + idx : undefined;
    }

    handleKeydown(event) {
        const opts = this._options;
        const key = event.key;
        const handled = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        if (!handled.includes(key)) {
            return;
        }
        event.preventDefault();
        if (!opts.length) {
            return;
        }
        const current = Math.max(
            0,
            opts.findIndex((o) => o.value === this.effectiveActiveValue)
        );
        let next = current;
        if (key === 'ArrowDown') {
            next = Math.min(current + 1, opts.length - 1);
        } else if (key === 'ArrowUp') {
            next = Math.max(current - 1, 0);
        } else if (key === 'Home') {
            next = 0;
        } else if (key === 'End') {
            next = opts.length - 1;
        } else {
            this.select(opts[current].value);
            return;
        }
        this._activeValue = opts[next].value;
    }

    handleClick(event) {
        const li = event.target.closest('li[role="option"]');
        if (!li) {
            return;
        }
        const idx = Array.from(this.template.querySelectorAll('li[role="option"]')).indexOf(li);
        if (idx < 0 || !this._options[idx]) {
            return;
        }
        const val = this._options[idx].value;
        this._activeValue = val;
        this.select(val);
    }

    select(val) {
        if (val === this._value) {
            return;
        }
        this._value = val;
        this._activeValue = val;
        this.dispatchEvent(new CustomEvent('change', { detail: { value: val } }));
    }
}
